interface ExpenseStore { fun save(expense: Expense) }
class LoggingStore(
    private val delegate: ExpenseStore,
) : ExpenseStore by delegate {
    override fun save(expense: Expense) {
        println("Saving ${expense.category}")
        delegate.save(expense)
    }
}

inline fun <reified T> Any?.isType(): Boolean = this is T

inline fun measure(label: String, block: () -> Unit) {
    val started = System.nanoTime()
    block()
    println("$label took ${System.nanoTime() - started}ns")
}

